task_slope <- function(tk) {
  e <- eff_tab[eff_tab$task == tk & eff_tab$position %in% c("1", "2", "3", "4"), , drop = FALSE]
  e <- e[order(as.numeric(e$position)), , drop = FALSE]
  d <- diff(e$estimate)
  stopifnot(nrow(e) == 4L, max(abs(d - mean(d))) < 1e-8)
  mean(d)
}
