insert_block_rules <- function(tab, block_rows) {
  lines <- strsplit(as.character(tab), "\n", fixed = TRUE)[[1]]
  lastfoot <- which(grepl("\\\\endlastfoot$", lines))
  if (length(lastfoot) == 1L) {
    data_idx <- which(seq_along(lines) > lastfoot[[1]] & grepl("\\\\\\\\$", lines))
  } else {
    mid <- which(grepl("\\\\midrule$", lines))
    bottom <- which(grepl("\\\\bottomrule$", lines))
    if (length(mid) < 1L || length(bottom) < 1L) {
      stop("fixed-effects table did not have a header rule", call. = FALSE)
    }
    data_idx <- which(
      seq_along(lines) > mid[[1]] &
        seq_along(lines) < bottom[[length(bottom)]] &
        grepl("\\\\\\\\$", lines)
    )
  }
  if (sum(block_rows) != length(data_idx)) {
    stop("block sizes do not match the fixed-effects rows", call. = FALSE)
  }
  ends <- cumsum(block_rows)
  ends <- ends[-length(ends)]
  for (k in rev(ends)) {
    lines <- append(lines, "\\midrule", after = data_idx[[k]])
  }
  paste(lines, collapse = "\n")
}
kable_page <- function(df, widths, block_rows = NULL, tabcolsep = "2.5pt", size = "\\small", escape = TRUE) {
  df <- format_coef_cols(df)
  if (!knitr::is_latex_output()) {
    plain <- names(df)
    plain <- gsub("\\\\shortstack\\{", "", plain)
    plain <- gsub("\\\\\\\\", " ", plain)
    plain <- gsub("\\}", "", plain)
    plain <- gsub("\\\\%", "%", plain)
    if ("Statistic" %in% names(df)) {
      df$Statistic <- sub("^z = ", "*z* = ", df$Statistic)
      df$Statistic <- sub("^t\\(", "*t*(", df$Statistic)
    }
    plain <- ifelse(plain %in% c("p", "N", "M", "SD", "n"), paste0("*", plain, "*"), plain)
    names(df) <- plain
    return(knitr::kable(df))
  }
  stopifnot(length(widths) == ncol(df))
  df[] <- lapply(df, style_stat_latex)
  nms <- names(df)
  nms <- latex_escape(nms)
  nms[nms %in% c("p", "N", "M", "SD", "n")] <- paste0("$", nms[nms %in% c("p", "N", "M", "SD", "n")], "$")
  names(df) <- nms
  tab <- knitr::kable(
    df,
    format = "latex",
    booktabs = TRUE,
    longtable = TRUE,
    align = widths,
    escape = FALSE,
    linesep = ""
  )
  tab <- sub(
    "\\begin{longtable}",
    paste0("\\begingroup\\setlength{\\tabcolsep}{", tabcolsep, "}", size, "\\begin{longtable}"),
    tab,
    fixed = TRUE
  )
  tab <- sub("\\end{longtable}", "\\end{longtable}\\endgroup", tab, fixed = TRUE)
  if (!is.null(block_rows)) tab <- insert_block_rules(tab, block_rows)
  knitr::asis_output(tab)
}
id_display <- function(id) {
  out <- id
  out[id == "S1"] <- "R1"
  out[id == "S2"] <- "R2"
  out
}
model_label <- function(id) {
  lab <- c(
    M1 = "Behavior",
    M2 = "Grip-period pupil",
    M3 = "Task-evoked pupil",
    M4a = "Pupil and sensitivity",
    M4b = "Pupil and sensitivity",
    M5 = "Missing pupil data"
  )
  out <- unname(lab[id])
  out[is.na(out)] <- NA_character_
  out
}
term_prose <- function(x) {
  x <- gsub("Grip-window", "Grip-period", x, fixed = TRUE)
  x <- gsub("^Effort\\b", "Physical effort", x, perl = TRUE)
  gsub("(?<!Physical )\\bEffort\\b", "physical effort", x, perl = TRUE)
}
sentence_case_term <- function(x) {
  vapply(strsplit(x, " ", fixed = TRUE), function(w) {
    if (length(w) > 1L) {
      rest <- w[-1L]
      keep <- grepl("^[A-Z0-9]{2,}$", rest)
      rest[!keep] <- tolower(rest[!keep])
      w[-1L] <- rest
    }
    paste(w, collapse = " ")
  }, character(1))
}
fixed_for_page <- function(fixed) {
  id <- id_display(fixed$ID)
  base <- model_label(fixed$ID)
  base <- ifelse(is.na(base), term_prose(fixed$Model), base)
  model <- paste0(base, " (", id, ")")
  model[id == "R1"] <- "Task-evoked area (R1)"
  not_ok <- !as.logical(fixed$Accepted)
  model[not_ok] <- paste0(id[not_ok], " (not accepted)")
  model[duplicated(id)] <- ""
  data.frame(
    Model = model,
    Term = sentence_case_term(term_prose(fixed$Term)),
    Estimate = fixed$Estimate,
    SE = fixed$SE,
    Statistic = fixed$Statistic,
    "95% CI" = fixed[["95% CI"]],
    p = fixed$p_tab,
    check.names = FALSE,
    stringsAsFactors = FALSE
  )
}
